      REAL FUNCTION DATAR(IADR)CC     FETCHES VALUE STORED OR REFERRED TO IN DATA ARRAYC CC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'CC     LOCAL VARIABLESC      EXTERNAL        IDATACC------------------------------------------------------C      IADS = IADR   10 IF (TIE(IADS) .EQ. 100) THEN        IADS = IDATA(IADS)        GO TO 10      ENDIF      DATAR = DATA(IADS)      RETURN      END